  <script>
    const chips = document.querySelectorAll(".filter-chip");
    const products = document.querySelectorAll(".product-card");

    chips.forEach((chip) => {
      chip.addEventListener("click", () => {
        chips.forEach((item) => item.classList.remove("active"));
        chip.classList.add("active");

        const filter = chip.dataset.filter;
        products.forEach((product) => {
          const matches = filter === "all" || product.dataset.category === filter;
          product.style.display = matches ? "grid" : "none";
        });
      });
    });

    const countdownNodes = document.querySelectorAll("#countdown .time-box strong");
    const dealDeadline = Date.now() + (2 * 24 * 60 * 60 + 7 * 60 * 60 + 12 * 60 + 30) * 1000;

    function updateCountdown() {
      const remaining = Math.max(0, dealDeadline - Date.now());
      const totalSeconds = Math.floor(remaining / 1000);
      const days = Math.floor(totalSeconds / 86400);
      const hours = Math.floor((totalSeconds % 86400) / 3600);
      const minutes = Math.floor((totalSeconds % 3600) / 60);
      const seconds = totalSeconds % 60;

      [days, hours, minutes, seconds].forEach((value, index) => {
        countdownNodes[index].textContent = String(value).padStart(2, "0");
      });
    }

    updateCountdown();
    setInterval(updateCountdown, 1000);

    const form = document.getElementById("newsletter-form");
    const email = document.getElementById("email");
    const toast = document.getElementById("toast");

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const value = email.value.trim();

      if (!value || !email.checkValidity()) {
        toast.textContent = "Enter a valid email to join After Hours.";
        toast.style.color = "var(--danger)";
        return;
      }

      toast.textContent = "You're in. Member access details are on the way.";
      toast.style.color = "var(--success)";
      form.reset();
    });
  </script>
